//! Members of jrsonnet's `std` and the parameters of its functions, as reported by the
//! evaluator (`FuncVal::params()`) at the pinned jrsonnet rev, without the `__` internals.
//! The table is generated by `scripts/gen-stdlib.sh`; rerun it when bumping the rev. A default
//! whose source isn't known is shown as `…`.

mod table;

pub use table::MEMBERS;

pub struct Member {
	pub name: &'static str,
	/// `None` for plain values such as `pi`.
	pub params: Option<&'static [&'static str]>,
}

pub fn find(name: &str) -> Option<&'static Member> {
	MEMBERS.iter().find(|m| m.name == name)
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn table_is_sane() {
		let mut names: Vec<_> = MEMBERS.iter().map(|m| m.name).collect();
		names.sort_unstable();
		let len = names.len();
		names.dedup();
		assert_eq!(names.len(), len, "duplicate members");
		assert!(MEMBERS.iter().all(|m| !m.name.starts_with("__")));
		assert!(
			find("length")
				.unwrap()
				.params
				.is_some_and(|p| !p.is_empty())
		);
		assert!(find("pi").unwrap().params.is_none());
		assert!(find("nope").is_none());
	}
}
